import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Toast","description":"","frontmatter":{},"headers":[],"relativePath":"components/toast.md","filePath":"components/toast.md"}'),s={name:"components/toast.md"};function n(d,t,i,h,c,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="toast" tabindex="-1">Toast <a class="header-anchor" href="#toast" aria-label="Permalink to &quot;Toast&quot;">​</a></h1><p>Toast is a short message in a corner of the screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to confirm what just happened, or to report a failure that needs no answer. Most toasts come from the toast store through a <a href="./toast-host">ToastHost</a>; a Toast placed by hand takes any of the four tones and one action, such as undo. A notice that stays until its cause is gone is a <a href="./banner">Banner</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tone</code></td><td><code>info</code></td><td><code>info</code>, <code>warn</code>, <code>error</code> or <code>ok</code></td></tr><tr><td><code>act</code></td><td></td><td>One action at the right end (a snippet)</td></tr><tr><td><code>children</code></td><td>required</td><td>The message</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It has the panel color, a strong line (red for an error), pad-md inside and the width of a toast (<code>--kata-width-toast</code>), never wider than its place. The icon takes the color of the tone and sits in a seat, centred on the ink of the first line of the text however it wraps (<a href="./../measuring#a-mark-beside-text">a mark beside text</a>); the icon, the text and the action are gap-sm apart, and the action is a small button at the right end that moves below the text when it does not fit. Its role is <code>alert</code> for an error and <code>status</code> otherwise.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/toast/" title="Toast" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/toast/" target="_blank" rel="noopener">Toast</a></figcaption></figure>',10)])])}const m=e(s,[["render",n]]);export{f as __pageData,m as default};
